import { publicUrl } from '@/lib/publicUrl';
import type { Hospital } from '@/types';

/**
 * Per-hospital homepage hero — ONE pre-composited photographic WebP
 * (hospital left + clean center + medication right), generated by
 * `npm run compose-heroes`.
 */
export interface HospitalHeroVisual {
  /** Flattened panoramic hero background. */
  composedHeroPath: string;
  /** CSS object-position for responsive cropping (mobile favors hospital). */
  objectPosition: string;
  /** Desktop/tablet object-position to keep center readable. */
  objectPositionDesktop: string;
}

const HERO_BY_SLUG: Record<string, HospitalHeroVisual> = {
  'king-salman': {
    composedHeroPath: publicUrl('assets/heroes/king-salman-hero.webp'),
    objectPosition: '18% center',
    objectPositionDesktop: 'center center',
  },
  'maternity-children': {
    composedHeroPath: publicUrl('assets/heroes/maternity-children-hero.webp'),
    objectPosition: '16% center',
    objectPositionDesktop: 'center center',
  },
  'hail-general': {
    composedHeroPath: publicUrl('assets/heroes/hail-general-hero.webp'),
    objectPosition: '20% center',
    objectPositionDesktop: 'center center',
  },
  'king-khalid': {
    composedHeroPath: publicUrl('assets/heroes/king-khalid-hero.webp'),
    objectPosition: '22% center',
    objectPositionDesktop: 'center center',
  },
  eradah: {
    composedHeroPath: publicUrl('assets/heroes/eradah-hero.webp'),
    objectPosition: '18% center',
    objectPositionDesktop: 'center center',
  },
};

const FALLBACK: HospitalHeroVisual = {
  composedHeroPath: publicUrl('assets/heroes/king-salman-hero.webp'),
  objectPosition: 'center center',
  objectPositionDesktop: 'center center',
};

/** Object-position for welcome cards (original hospital photos, not composited heroes). */
const CARD_FOCUS: Record<string, string> = {
  'king-salman': '18% center',
  'maternity-children': '35% center',
  'hail-general': '42% center',
  'king-khalid': '45% center',
  eradah: '40% center',
};

export function hospitalPhotoObjectPosition(slug: string): string {
  return CARD_FOCUS[slug] ?? 'center center';
}

/** Resolve the single pre-composited hero background for a hospital. */
export function resolveHospitalHeroVisual(
  hospital: Pick<Hospital, 'slug' | 'imagePath' | 'nameEn'>,
): HospitalHeroVisual {
  return HERO_BY_SLUG[hospital.slug] ?? FALLBACK;
}
